/* ---------- Pricing (shared by admin and the Agency portal) ---------- */
// F4: NVQ programmes can be bundled — one NVQ seat covers the learner's NVQ fees (Browse catalogue prices)
const NVQ_FEES = { 'Level 2 Diploma in Care (England)': 1800, 'Level 3 Diploma in Adult Care (England)': 2400, 'Level 5 Diploma in Leadership and Management for Adult Care': 3600 };
const nvqBundleCourses = () => (ADMIN.programmes || []).filter(p => p.status === 'Active' && NVQ_FEES[p.title]).map(p => ({ title: p.title, gbp: NVQ_FEES[p.title], status: 'Published', nvq: true }));
const coursePrice = t => (ADMIN.courses.find(x => x.title === t) || nvqBundleCourses().find(x => x.title === t) || { gbp: 35 }).gbp;
const floorPct = () => { const c = (ADMIN.config || []).find(x => x.name === 'Bundle minimum price'); const m = c && c.value.match(/(\d+)%/); return m ? +m[1] : 20; };
function priceOf(p, cur = p.cur, qty = p.seats) {
  const list = p.courses.reduce((s, t) => s + coursePrice(t), 0) * qty;
  let pct = 0, final, label;
  if (p.customTotal) { final = Math.round(p.customTotal / p.seats * qty); pct = Math.round((1 - final / list) * 100); label = 'Negotiated price'; }
  else if (p.pct != null) { pct = p.pct; final = Math.round(list * (1 - pct / 100)); label = `Discount −${pct}%`; }
  else { const sl = (p.slabs || AUTO_SLABS).find(s => qty >= s[0]); pct = sl ? sl[1] : 0; final = Math.round(list * (1 - pct / 100)); label = sl ? `Volume price: ${sl[0]}+ seats −${pct}%` : 'Standard price'; }
  const floor = Math.round(list * (1 - floorPct() / 100));
  return { list, pct, final, floor, margin: final - floor, below: final < floor, label, cur };
}
const FLOOR_TONE = { Above: 'green', 'Below — pending': 'amber', 'Below — approved': 'blue', 'Below — rejected': 'red', 'Below — returned': 'amber', 'Below — not submitted': 'red' };
function floorStatus(p) { const pr = priceOf(p); if (!pr.below) return 'Above'; const f = p.floor || {}; return { Pending: 'Below — pending', Approved: 'Below — approved', Rejected: 'Below — rejected', Returned: 'Below — returned' }[f.state] || 'Below — not submitted'; }
// Agency portal Buy Bundles reads the published catalogue; customised products appear only for their agency
AGY_CATALOGUE = function () {
  return (STORE.biz ? STORE.biz.products : []).filter(p => p.status === 'Published' && (!p.agency || p.agency === AGN()))
    .map(p => ({ id: p.id, name: p.name, courses: p.courses, seats: p.seats, days: p.days, custom: p.agency, fixedPct: p.pct, slabs: p.slabs, customTotal: p.customTotal, unit: p.courses.reduce((s, t) => s + coursePrice(t), 0) }));
};
priceFor = function (c, qty) {
  const list = c.unit * qty;
  if (c.customTotal) { const total = Math.round(c.customTotal / c.seats * qty); return { list, pct: Math.max(0, Math.round((1 - total / list) * 100)), total, label: `Customised for ${AGN()}: negotiated price` }; }
  if (c.fixedPct != null) return { list, pct: c.fixedPct, total: Math.round(list * (1 - c.fixedPct / 100)), label: c.custom ? `Customised for ${AGN()}: −${c.fixedPct}%` : `Discount −${c.fixedPct}%` };
  const sl = (c.slabs || SLABS).find(s => qty >= s[0]), pct = sl ? sl[1] : 0;
  return { list, pct, total: Math.round(list * (1 - pct / 100)), label: pct ? `Volume price: ${sl[0]}+ seats −${pct}%` : 'Standard price' };
};

